import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=";", quotechar='"'))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])

    used_names = set(columns)
    while len(columns) < width:
        base = "extra_" + str(len(columns) + 1)
        name = base
        suffix = 2
        while name in used_names:
            name = base + "_" + str(suffix)
            suffix += 1
        columns.append(name)
        used_names.add(name)

    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
